head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > E > onkeyup]<br/>컴포넌트가 포커스된 상태에서 눌렀던 키보드의 키를 떼면 발생합니다.",
    "validation" : [
        "컴포넌트가 포커스된 상태에서 눌렀던 키보드의 키를 떼면 발생하여야 합니다.",
        "renderType=component 일때 버튼 영역에서 Enter 키 입력 시 onkeyup 이벤트는 발생하지 않습니다.",
    ]
} 



scwin.wf_sample_onwframeload = function () {
    // 테스트 설명, 유효성 생성
    let wf_body_left = wf_sample.getObj("wf_body_left");
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	
};



scwin.onpageload = function () {
    // Global DataList 생성 함수 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        renderType: "component",
    }

    let cList = $c.gcm.createCList(properties);

    let eList = $c.gcm.createEList(["onkeydown", "onkeyup"]);

    // comp 생성 함수 호출    
    $c.gcm.createBasicInputCalendar(cList, eList);

    wf_sample.getObj("con_dataType").setDisabled(true);
}
